/* @autogenerated */
import { TestBed } from '@angular/core/testing';
import { TranslocoService } from '@jsverse/transloco';
import { BehaviorSubject } from 'rxjs';
import { FeaturesSectionComponent } from './features-section.component';

describe('FeaturesSectionComponent', () => {
  let items: BehaviorSubject<unknown>;

  const create = () => {
    TestBed.configureTestingModule({
      imports: [FeaturesSectionComponent],
      providers: [{ provide: TranslocoService, useValue: { selectTranslateObject: () => items } }],
    });
    TestBed.overrideComponent(FeaturesSectionComponent, { set: { template: '' } });
    const fixture = TestBed.createComponent(FeaturesSectionComponent);
    fixture.detectChanges();
    return fixture.componentInstance;
  };

  beforeEach(() => {
    items = new BehaviorSubject<unknown>({
      identity: { icon: 'badge', title: 'Identity', text: 'Users' },
      access: { title: 'Access', text: 'Clients' },
    });
  });

  afterEach(() => TestBed.resetTestingModule());

  it('lists the features of the i18n in their order', () => {
    const section = create();

    expect(section.features().map((f) => f.key)).toEqual(['identity', 'access']);
    expect(section.features()[0]).toEqual({ key: 'identity', icon: 'badge', title: 'Identity', text: 'Users' });
  });

  it('shows no features when the i18n has none (the key comes back as text)', () => {
    items.next('sections.features.items');

    expect(create().features()).toEqual([]);
  });

  it('follows the language changes', () => {
    const section = create();
    items.next({ identity: { title: 'Identidad', text: 'Usuarios' } });

    expect(section.features()).toEqual([{ key: 'identity', title: 'Identidad', text: 'Usuarios' }]);
  });
});
